class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        pos = {}
        for i, v in enumerate(nums):
            pos.setdefault(v, []).append(i)
        best = n
        for v, p in pos.items():
            if len(p) == n:
                return 0
            maxgap = 0
            k = len(p)
            for j in range(k - 1):
                g = p[j + 1] - p[j] - 1
                if g > maxgap:
                    maxgap = g
            wrap = p[0] + n - p[-1] - 1
            if wrap > maxgap:
                maxgap = wrap
            t = (maxgap + 1) // 2
            if t < best:
                best = t
        return best
