class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        pos = {}
        for i, v in enumerate(nums):
            pos.setdefault(v, []).append(i)
        best = n
        for v, ps in pos.items():
            k = len(ps)
            worst = 0
            for j in range(k):
                cur = ps[j]
                if j + 1 < k:
                    nxt = ps[j + 1]
                else:
                    nxt = ps[0] + n
                g = nxt - cur - 1
                need = (g + 1) // 2
                if need > worst:
                    worst = need
                    if worst >= best:
                        break
            if worst < best:
                best = worst
        return best
