from collections import defaultdict

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        pos = defaultdict(list)
        for i, v in enumerate(nums):
            pos[v].append(i)
        best = n
        for v, p in pos.items():
            if len(p) == n:
                return 0
            worst = 0
            k = len(p)
            for j in range(k - 1):
                gap = p[j + 1] - p[j] - 1
                worst = max(worst, (gap + 1) // 2)
            gap = p[0] + n - p[-1] - 1
            worst = max(worst, (gap + 1) // 2)
            best = min(best, worst)
        return best

