import json
import itertools
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # all equal
        v = draw(st.integers(1, 3))
        nums = [v] * n
    elif mode == 1:
        # sorted or reverse-sorted
        nums = sorted(draw(st.lists(st.integers(1, 3), min_size=n, max_size=n)))
        if draw(st.booleans()):
            nums = nums[::-1]
    else:
        nums = draw(st.lists(st.integers(1, 3), min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    for x in nums:
        if type(x) is not int or not (1 <= x <= 10**9):
            return False
    # keep brute-force tractable for the spec's own tests
    return n <= 6 and all(x <= 3 for x in nums) or (1 <= n <= 10**5)

def ref(inp):
    nums = tuple(json.loads(inp))
    n = len(nums)
    # Literal simulation: maintain the set of all arrays reachable after t seconds.
    # The answer is the least t for which some reachable array is constant.
    cur = {nums}
    t = 0
    while True:
        for arr in cur:
            if all(x == arr[0] for x in arr):
                return json.dumps(t)
        nxt = set()
        for arr in cur:
            choices = []
            for i in range(n):
                choices.append((arr[i], arr[(i - 1 + n) % n], arr[(i + 1) % n]))
            for combo in itertools.product(*choices):
                nxt.add(combo)
        cur = nxt
        t += 1
